    cast(SmallBannerPhotoUrl as string)                                             as small_banner_photo_url,
    cast(MediumBannerPhotoUrl as string)                                            as medium_banner_photo_url,
    cast(IsProfilePhotoActive as boolean)                                           as is_profile_photo_active,
